-- PT110-S3-Q7. Batch 06.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT110-S3-Q7$batch06$ AND q.stimulus=$batch06$Dr. Jones: The new technology dubbed "telemedicine" will provide sustained improvement in at least rural patient care since it allows rural physicians to televise medical examinations to specialists who live at great distances-specialists who will thus be able to provide advice the rural patient would otherwise not receive.

Dr. Carabella: Not so. Telemedicine might help rural patient care initially. However, small hospitals will soon realize that they can minimize expenses by replacing physicians with technicians who can use telemedicine to transmit examinations to large medical centers, resulting in fewer patients being able to receive traditional, direct medical examination. Eventually, it will be the rare individual who ever gets truly personal attention. Hence, rural as well as urban patient care will suffer.$batch06$ AND q.prompt=$batch06$Which one of the following is a point at issue between Dr. Jones and Dr. Carabella?$batch06$ AND q.correct_choice=$batch06$E$batch06$) THEN RAISE EXCEPTION 'Question changed: PT110-S3-Q7'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch06$PT110-S3-Q7$batch06$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT110-S3-Q7'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT110-S3-Q7$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Dr. Jones's Position$batch06$, $batch06$Telemedicine will bring sustained improvement to rural patient care.$batch06$), (1, $batch06$Dr. Carabella's Position$batch06$, $batch06$It may help at first, but in the long run rural and urban care will suffer.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$Carabella grants a short-term benefit, so that is not the dispute. The key word in Jones's claim is "sustained." Carabella says the long run gets worse. So they disagree about the long run.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Whether telemedicine will benefit rural patients over the long run.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT110-S3-Q7$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$Neither compares the quality of specialists' advice with rural doctors'.$batch06$), ($batch06$B$batch06$, $batch06$Where telemedicine gets installed never comes up.$batch06$), ($batch06$C$batch06$, $batch06$Neither speaker disputes whether telemedicine will be adopted. Carabella's worry assumes it will be.$batch06$), ($batch06$D$batch06$, $batch06$This is the most popular wrong answer. Jones talks about specialists' advice reaching rural patients, but Carabella never addresses whether the patients who need it most will get it. Her worry is about personal attention in general.$batch06$), ($batch06$E$batch06$, $batch06$Jones says "sustained improvement" for rural care. Carabella says rural care "will suffer" eventually.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT110-S3-Q7$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
